using System.Diagnostics;
using System.Text.Json.Nodes;
using ZrConfig.Core;

// Separate processes exercise the real catalogs and manager implementations. These
// samples do not contaminate cold-load/query allocation windows in other reports.
internal static class ServerRuntimeControlBenchmarks
{
    internal static void WriteGraphs(string output,List<object> builds)
    {
        foreach(string kind in new[]{"chain","dense","independent"})
        {
            int count=kind=="dense"?256:10000;
            string Name(int i)=>"N"+i.ToString("D5",System.Globalization.CultureInfo.InvariantCulture);
            var source=Enumerable.Range(0,count).Select(i=>(Name:Name(i),Hash:"hash",Dependencies:kind=="dense"?Enumerable.Range(0,count).Where(j=>j!=i).Select(Name).ToArray():kind=="chain"&&i+1<count?new[]{Name(i+1)}:Array.Empty<string>())).ToArray();
            var samples=new double[3];RuntimeCatalogDescriptor? catalog=null;
            for(int repeat=0;repeat<3;repeat++){var timer=Stopwatch.StartNew();catalog=RuntimeCatalog.Create(source);samples[repeat]=timer.Elapsed.TotalMilliseconds;}
            if(catalog!.Tables.Length!=count||catalog.Components.Length!=(kind=="dense"?1:count))throw new Exception("Graph SCC mismatch");
            string json=catalog.Serialize();File.WriteAllText(Path.Combine(output,"graph-"+kind+".json"),json);
            builds.Add(new{language="generator-graph",kind,tables=count,edges=source.Sum(t=>t.Dependencies.Length),components=catalog.Components.Length,scc_samples_ms=samples,catalog_bytes=System.Text.Encoding.UTF8.GetByteCount(json)});
        }
    }
    internal static void Validate(JsonNode[] values,string language,bool locks=false)
    {
        if(values.Length!=(locks?8:7))throw new Exception("Control scenario count: "+language);
        var initialization=values.Single(s=>s["scenario"]!.GetValue<string>()=="initialization");if(initialization["verified"]!.GetValue<bool>()!=true||!double.IsFinite(initialization["elapsed_ms"]!.GetValue<double>())||initialization["elapsed_ms"]!.GetValue<double>()<0)throw new Exception("Initialization evidence: "+language);
        if(locks){var row=values.Single(s=>s["scenario"]!.GetValue<string>()=="locks");bool applicable=language is not("typescript" or "lua");if(row["applicable"]!.GetValue<bool>()!=applicable||applicable&&(row["acquisitions"]!.GetValue<long>()<=0||row["acquisition_ns"]!.GetValue<long>()<row["max_acquisition_ns"]!.GetValue<long>()))throw new Exception("Lock coverage: "+language);}
        foreach(string kind in new[]{"chain","dense","independent"})
        {
            var row=values.Single(s=>s["scenario"]!.GetValue<string>()=="graph"&&s["kind"]!.GetValue<string>()==kind);
            if(row["selected"]!.GetValue<int>()!=(kind=="chain"?10000:kind=="dense"?256:1)||row["selections"]!.GetValue<int>()!=20)throw new Exception("Graph closure: "+language);
            foreach(string field in new[]{"parse_ms","select_ms"})if(!double.IsFinite(row[field]!.GetValue<double>())||row[field]!.GetValue<double>()<0)throw new Exception("Graph timer: "+language);
        }
        foreach(string scenario in new[]{"cancel","contention","slow-reader"})
        {
            var row=values.Single(s=>s["scenario"]!.GetValue<string>()==scenario);
            if(row["verified"]?.GetValue<bool>()!=true)throw new Exception("Control invariant: "+language+"/"+scenario);
            if(scenario=="cancel")
            {
                var samples=row["samples_ms"]!.AsArray();
                if(samples.Count!=100||samples.Any(s=>!double.IsFinite(s!.GetValue<double>())||s.GetValue<double>()<0))throw new Exception("Cancellation distribution: "+language);
            }
        }
    }
    internal static string Extend(string source,string language)
    {
        void Insert(string marker,string content){if(!source.Contains(marker,StringComparison.Ordinal))throw new Exception("Control insertion: "+language+"/"+marker);source=source.Replace(marker,content+"\n"+marker,StringComparison.Ordinal);}
        switch(language)
        {
            case "csharp":Insert(" public static void Run",CSharp);Insert("Console.WriteLine(JsonSerializer.Serialize(new{cold_ms","Controls(a,snapshot);");break;
            case "java":Insert(" public static void main",Java);Insert("sink=sum;","controls(a,s);");break;
            case "go":source=source.Replace("\"testing\";\"time\"","\"testing\";\"time\";\"sync\"");Insert("func TestBenchmarkProcess",Go);Insert("bytes,_:=json.Marshal","controls(t,args,s);");break;
            case "cpp":source="#include <thread>\n"+source;Insert("int main(int,char** a)",Cpp);Insert("t=Clock::now();s.reset();","controls(a,s);");break;
            case "rust":Insert("fn main(){",Rust);Insert("t=Instant::now();drop(s);","controls(&a,&s);");break;
            case "typescript":source=TypeScript+"\n"+source;Insert("setImmediate(()=>console.log","controls(a,s);");break;
            case "lua":source=Lua+"\n"+source;Insert("print(string.format('{\"cold_ms\"","controls(arg,s);");break;
            default:throw new ArgumentException(language);
        }
        return Initialization(source,language);
    }
    internal static void PrepareInitialization(string generated)
    {
        string path=Path.Combine(generated,"Go","server.go"),source=File.ReadAllText(path);
        const string before="var serverCatalog = newCatalog(";
        if(!source.Contains(before,StringComparison.Ordinal))throw new Exception("Missing Go catalog initialization");
        File.WriteAllText(path,source.Replace(before,"var serverCatalog = controlInitialCatalog(",StringComparison.Ordinal));
    }
    private static string Initialization(string source,string language)
    {
        var change=language switch{
            "csharp"=>("using var manager=new Manager", "var initClock=Stopwatch.StartNew();var initCatalog=ZrConfig.Models.ServerCatalog.Instance;double initMs=initClock.Elapsed.TotalMilliseconds;Console.WriteLine(JsonSerializer.Serialize(new{scenario=\"initialization\",scope=\"first-catalog-access\",elapsed_ms=initMs,verified=initCatalog.Tables.Count==3}));using var manager=new Manager"),
            "java"=>("var retained=new ArrayList<DataSnapshot>();", "long initStart=System.nanoTime();var initCatalog=ServerConfig.catalog();if(initCatalog.tables.size()!=3)throw new AssertionError();System.out.printf(Locale.ROOT,\"{\\\"scenario\\\":\\\"initialization\\\",\\\"scope\\\":\\\"first-catalog-access\\\",\\\"elapsed_ms\\\":%.6f,\\\"verified\\\":true}%n\",ms(initStart));var retained=new ArrayList<DataSnapshot>();"),
            "go"=>("ctx:=context.Background();mode:=", "fmt.Printf(\"{\\\"scenario\\\":\\\"initialization\\\",\\\"scope\\\":\\\"package-catalog-initializer\\\",\\\"elapsed_ms\\\":%.6f,\\\"verified\\\":true}\\n\",controlInitializationMilliseconds);ctx:=context.Background();mode:="),
            "cpp"=>("Cancellation token;std::vector<std::shared_ptr<const data::Snapshot>> retained;", "auto init_start=Clock::now();auto& init_catalog=server::Snapshot::catalog();if(init_catalog.tables().size()!=3)throw std::logic_error(\"Catalog initialization\");std::cout<<\"{\\\"scenario\\\":\\\"initialization\\\",\\\"scope\\\":\\\"first-catalog-access\\\",\\\"elapsed_ms\\\":\"<<ms(init_start)<<\",\\\"verified\\\":true}\\n\";Cancellation token;std::vector<std::shared_ptr<const data::Snapshot>> retained;"),
            "rust"=>("let mut retained=Vec::new();", "let init_start=Instant::now();let init_catalog=zrconfig::server::Snapshot::catalog().unwrap();assert_eq!(init_catalog.tables().len(),3);println!(\"{{\\\"scenario\\\":\\\"initialization\\\",\\\"scope\\\":\\\"first-catalog-access\\\",\\\"elapsed_ms\\\":{},\\\"verified\\\":true}}\",ms(init_start));let mut retained=Vec::new();"),
            "typescript"=>("D=require(path.join(process.argv[2],'dist/data.js'));", "D=(()=>{const start=performance.now(),value=require(path.join(process.argv[2],'dist/data.js'));console.log(JSON.stringify({scenario:'initialization',scope:'first-data-module-import',elapsed_ms:performance.now()-start,verified:typeof value.Snapshot==='function'}));return value;})();"),
            "lua"=>("local D=require('data');local root", "local init_start=os.clock();local D=require('data');print(string.format('{\"scenario\":\"initialization\",\"scope\":\"first-data-module-import\",\"elapsed_ms\":%.6f,\"verified\":true}',(os.clock()-init_start)*1000));local root"),_=>throw new ArgumentException(language)};
        if(!source.Contains(change.Item1,StringComparison.Ordinal))throw new Exception("Initialization insertion: "+language);
        source=source.Replace(change.Item1,change.Item2,StringComparison.Ordinal);
        if(language=="go")source+="\nvar controlInitializationMilliseconds float64\nfunc controlInitialCatalog(source string)*Catalog{start:=time.Now();value:=newCatalog(source);controlInitializationMilliseconds=float64(time.Since(start))/float64(time.Millisecond);return value}\n";
        return source;
    }
