function controls(a,snapshot){
 const R=require(require('path').join(process.argv[2],'dist/runtime.js')),fs=require('fs');
 for(const kind of ['chain','dense','independent']){const json=fs.readFileSync(require('path').join(a[0],'graph-'+kind+'.json'),'utf8');let now=performance.now();const graph=new R.Catalog(json),parse=performance.now()-now;now=performance.now();let selected=0;for(let i=0;i<20;i++)selected=graph.select(['N00000']).tables.length;console.log(JSON.stringify({scenario:'graph',kind,parse_ms:parse,select_ms:performance.now()-now,selected,selections:20}));}
 const owner=new R.ServerManager(),file=new R.FileConfigSource(a[0]);owner.reload(()=>snapshot,new R.Cancellation());const samples=[];for(let i=0;i<100;i++){const token=new R.Cancellation();let reads=0,start=0;const source={read:(path,max,cancellation)=>{if(++reads===2){start=performance.now();token.cancel();}return file.read(path,max,cancellation);}};let cancelled=false;try{owner.prepare(()=>D.Snapshot.load(source,{mode:'LazyRowsOnAccess',tables:['Bench'],preferJSON:a[1]==='json'},token),token).discard();}catch(e){if(e.code!=='Cancelled')throw e;cancelled=true;}if(!cancelled||reads!==2||owner.acquireSnapshot()!==snapshot||owner.status().generation!==1n||owner.diagnostics().activePreparations!==0)throw Error('Cancel invariant');samples.push(performance.now()-start);}console.log(JSON.stringify({scenario:'cancel',samples_ms:samples,verified:true,point:'second-source-read'}));
 const now=performance.now();for(let i=0;i<100;i++){owner.reload(()=>snapshot,new R.Cancellation());for(let j=0;j<400;j++)if(owner.acquireSnapshot()!==snapshot)throw Error('Mixed snapshot');}if(owner.status().generation!==101n)throw Error('Update count');console.log(JSON.stringify({scenario:'contention',readers:1,reads:40000,updates:100,elapsed_ms:performance.now()-now,verified:true,threaded:false,includes_prepare_io:false}));const row=snapshot.get_Bench().get(1);owner.clear();owner.close();if(row.Id!==1||snapshot.get_Bench().get(2).Id!==2)throw Error('Slow reader');console.log(JSON.stringify({scenario:'slow-reader',held_updates:100,verified:true}));
